#!/usr/bin/env bash
#MISE description="Gate: the per-suite cost corpus names every suite and only real ones (CLOUD-352)"
#
# WHAT THIS DOES AND DELIBERATELY DOES NOT DO. `bench/suites/RESULTS.md` records
# how long each bats suite takes. It is regenerated by `mise run suite-bench`
# from the report `test:bats` leaves behind.
#
# It is NOT byte-diffed against a fresh run, and that is the whole design
# decision. `token-bench-check` can diff its corpus because token counts are
# deterministic: the same fixtures yield the same numbers on any machine. Wall
# clock is not — the same suite varies with load, and a gate demanding byte
# equality on a duration would be red on every second run and would be bypassed
# within a day. Durations are a CLOCK, and `.claude/rules/toolchain.md` puts a
# clock in a drift job rather than in the gate.
#
# WHAT IS DETERMINISTIC IS MEMBERSHIP, and that is what rots. A suite added and
# never recorded is invisible to anything reading the corpus; a row naming a
# suite that was deleted is a figure attached to nothing. Both are decidable
# from committed text alone, at no runtime cost, and both are what make the
# corpus trustworthy enough to answer "is the file I am editing expensive".
#
# Pointer-only per non-negotiable 4: the suite name and which direction failed.
# Never a duration — a number here would be a second authority over the corpus.
#
# Exit 0 the corpus covers exactly the tracked suites / 1 it does not / 2 could
# not look.
set -uo pipefail

cd "$(git rev-parse --show-toplevel)" || exit 2

readonly CORPUS="${SUITE_BENCH_CORPUS:-bench/suites/RESULTS.md}"
readonly SUITES="${SUITE_BENCH_SUITES:-tests}"

if [[ ! -f "$CORPUS" ]]; then
	echo "::error:: suite-bench-check: $CORPUS is missing, so nothing records what the suite costs. Run \`mise run test:bats\` then \`mise run suite-bench --write\`." >&2
	exit 2
fi

# The tracked suites, from git rather than the working tree: an untracked scratch
# file beside the suites is not something the corpus should have to carry.
tracked=$(git ls-files "$SUITES/*.bats" 2>/dev/null | sort)
if [[ -z "${tracked//[[:space:]]/}" ]]; then
	echo "::error:: suite-bench-check: no tracked .bats suites under $SUITES/, so the corpus has no subject. This is could-not-look, not a clean corpus." >&2
	exit 2
fi

# The corpus rows: the path inside the third column's backticks, tolerant of the
# padding a table formatter adds. Not cosmetic — `prettier` owns Markdown in this
# repository and aligns table columns, and the first version of this pattern
# required exactly one space before the closing pipe. Run against a formatted
# corpus it matched no row at all and reported every tracked suite as missing:
# 150 findings, all false, from a gate that looked like it was working.
# shellcheck disable=SC2016 # the `$`/backtick here are sed and Markdown syntax, not shell expansions
recorded=$(sed -n 's/^|[^|]*|[^|]*|[[:space:]]*`\([^`]*\)`[[:space:]]*|[[:space:]]*$/\1/p' "$CORPUS" | sort)
if [[ -z "${recorded//[[:space:]]/}" ]]; then
	echo "::error:: suite-bench-check: $CORPUS carries no suite rows, so it records nothing. This is could-not-look, not a clean corpus." >&2
	exit 2
fi

status=0

# Anchored on each loop's own condition, not on `status=1`: both assignments sit
# at the same indentation, so an indentation-keyed script either matches nothing
# (the first attempt, reported `inert-mutation`) or matches both refusals at once
# and proves neither.
#MUTANT missing-suite-admitted|s@if ! grep -qxF "\$suite" <<<"\$recorded"; then@if false; then@|a suite absent from the corpus is refused
#MUTANT phantom-row-admitted|s@if ! grep -qxF "\$row" <<<"\$tracked"; then@if false; then@|a corpus row naming no real suite is refused
while IFS= read -r suite; do
	[[ -n "$suite" ]] || continue
	if ! grep -qxF "$suite" <<<"$recorded"; then
		echo "::error:: suite-bench-check: $suite is tracked but absent from $CORPUS, so nothing records what it costs and an author editing it is told nothing. Regenerate with \`mise run suite-bench --write\`." >&2
		status=1
	fi
done <<<"$tracked"

while IFS= read -r row; do
	[[ -n "$row" ]] || continue
	if ! grep -qxF "$row" <<<"$tracked"; then
		echo "::error:: suite-bench-check: $CORPUS records $row, which is not a tracked suite — a cost attached to nothing. Regenerate with \`mise run suite-bench --write\`." >&2
		status=1
	fi
done <<<"$recorded"

if [[ "$status" -eq 0 ]]; then
	echo "suite-bench-check: $(wc -l <<<"$tracked" | tr -d ' ') tracked suite(s), each recorded in $CORPUS and none recorded that is not tracked"
fi
exit "$status"
